import xml.etree.ElementTree as ET
from collections import deque

# Parse the network file
tree = ET.parse('/Users/mizmorchang/Desktop/newest/AgentSUMO/SUMOLanguageExpert/grid_experiment/experiment_setup/data/network/grid_11x11.net.xml')
root = tree.getroot()

# Collect all edges
edges = {}
for edge in root.findall('edge'):
    edge_id = edge.get('id')
    from_node = edge.get('from')
    to_node = edge.get('to')
    if edge_id and from_node and to_node:
        edges[edge_id] = {'from': from_node, 'to': to_node}

# Build edge adjacency using connections
edge_successors = {e: [] for e in edges}
for conn in root.findall('connection'):
    from_edge = conn.get('from')
    to_edge = conn.get('to')
    if from_edge in edge_successors and to_edge in edges:
        if to_edge not in edge_successors[from_edge]:
            edge_successors[from_edge].append(to_edge)

# BFS to find shortest path in number of hops
def bfs_hops(graph, start, goal):
    if start == goal:
        return 0
    visited = {start}
    queue = deque([(start, 0)])
    while queue:
        current, hops = queue.popleft()
        for neighbor in graph[current]:
            if neighbor == goal:
                return hops + 1
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, hops + 1))
    return -1  # not reachable

hops = bfs_hops(edge_successors, 'D5E5', 'D2C2')
print(f"Shortest path distance (hops) from D5E5 to D2C2: {hops}")

# Also trace the path for verification
def bfs_path(graph, start, goal):
    if start == goal:
        return [start]
    visited = {start: None}
    queue = deque([start])
    while queue:
        current = queue.popleft()
        for neighbor in graph[current]:
            if neighbor not in visited:
                visited[neighbor] = current
                if neighbor == goal:
                    # Reconstruct path
                    path = []
                    node = goal
                    while node is not None:
                        path.append(node)
                        node = visited[node]
                    return list(reversed(path))
                queue.append(neighbor)
    return None

path = bfs_path(edge_successors, 'D5E5', 'D2C2')
print(f"Path: {path}")
print(f"Number of hops (edges traversed): {len(path) - 1}")
